<script setup lang="ts">
import { h,onMounted,ref } from 'vue'
import { NAlert,NButton,NCheckbox,NDataTable,NFormItem,NInput,NInputNumber,NModal,NPopconfirm,NSelect,NTag,useMessage } from 'naive-ui'
import { api } from '../api'
import NodeRouting from './NodeRouting.vue'
import {nodeRouting} from '../forms'
const message=useMessage(),rows=ref<any[]>([]),nodes=ref<any[]>([]),busy=ref(false),error=ref(''),show=ref(false),links=ref(''),profiles=ref<any[]>([]),issues=ref<any[]>([]),storageReady=ref(true),saving=ref(false),previewed=ref(false)
const editor=ref(false),editJSON=ref(''),editIndex=ref<number|null>(null),editID=ref<number|null>(null),editError=ref('')
const deleting=ref(new Set<number>())
async function removeExit(row:any){if(deleting.value.has(row.id))return;deleting.value.add(row.id);try{await api('/api/admin/exits/'+row.id,{method:'DELETE'});message.success('落地已删除');await load()}catch(e){message.error((e as Error).message);return false}finally{deleting.value.delete(row.id)}}
const routeModal=ref(false),nodeID=ref<number|null>(null),defaultExit=ref(0),globalExit=ref(false),routeRules=ref<any[]>([]),routeError=ref('')
async function load(){busy.value=true;error.value='';try{[rows.value,nodes.value]=await Promise.all([api('/api/admin/exits'),api('/api/admin/nodes')])}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function openImport(){links.value='';profiles.value=[];issues.value=[];previewed.value=false;show.value=true;error.value=''}
async function parse(){saving.value=true;error.value='';try{const p=await api('/api/admin/exits/parse',{method:'POST',body:JSON.stringify({links:links.value})});profiles.value=p.profiles.map((x:any)=>({...x,selected:true}));issues.value=p.issues;storageReady.value=p.storage_ready;previewed.value=true;links.value=''}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function saveImport(){saving.value=true;error.value='';try{const selected=profiles.value.filter(x=>x.selected).map(({selected,...p})=>p);await api('/api/admin/exits',{method:'POST',body:JSON.stringify({profiles:selected})});show.value=false;profiles.value=[];message.success('落地已加密保存');await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function edit(row:any,index:number|null=null){editError.value='';editIndex.value=index;editID.value=index===null?row.id:null;try{const p=index===null?await api('/api/admin/exits/'+row.id):row;const {selected,...profile}=p;editJSON.value=JSON.stringify(profile,null,2);editor.value=true}catch(e){message.error((e as Error).message)}}
async function saveEdit(){saving.value=true;editError.value='';try{const p=JSON.parse(editJSON.value);if(editIndex.value!==null)profiles.value[editIndex.value]={...p,selected:profiles.value[editIndex.value].selected};else{await api('/api/admin/exits/'+editID.value,{method:'PATCH',body:JSON.stringify({profile:p})});await load()};editor.value=false;editJSON.value=''}catch(e){editError.value=(e as Error).message}finally{saving.value=false}}
async function toggle(row:any){try{await api('/api/admin/exits/'+row.id,{method:'PATCH',body:JSON.stringify({active:!row.active})});await load()}catch(e){message.error((e as Error).message)}}
const columns=[{title:'名称',key:'name',minWidth:150},{title:'协议',key:'protocol',minWidth:130},{title:'地址',key:'server',minWidth:220,render:(r:any)=>(r.server.includes(':')?'['+r.server+']':r.server)+':'+r.port},{title:'状态',key:'active',width:85,render:(r:any)=>h(NTag,{type:r.active?'success':'default',bordered:false,size:'small'},()=>r.active?'启用':'停用')},{title:'操作',key:'actions',width:230,fixed:'right' as const,render:(r:any)=>h('div',{class:'button-row'},[h(NButton,{size:'small',quaternary:true,onClick:()=>edit(r)},()=> '编辑'),h(NButton,{size:'small',quaternary:true,onClick:()=>toggle(r)},()=>r.active?'停用':'启用'),h(NPopconfirm,{onPositiveClick:()=>removeExit(r),positiveButtonProps:{loading:deleting.value.has(r.id)}},{trigger:()=>h(NButton,{size:'small',quaternary:true,type:'error',disabled:deleting.value.has(r.id)},()=> '删除'),default:()=>`确定删除落地“${r.name}”？连接凭据将被移除，仍被节点引用时无法删除。`})])}]
async function selectNode(id:number|null){nodeID.value=id;routeError.value='';if(!id)return;try{const r=await api(`/api/admin/nodes/${id}/exits`);defaultExit.value=r.default_exit;globalExit.value=r.global??defaultExit.value>0;routeRules.value=(r.rules||[]).map((x:any)=>({exit_id:x.exit_id,domains:(x.domain_suffixes||[]).join('\n'),cidrs:(x.ip_cidrs||[]).join('\n')}))}catch(e){routeError.value=(e as Error).message}}
const lines=(s:string)=>s.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean)
async function saveRoutes(){if(!nodeID.value)return;saving.value=true;routeError.value='';try{await api(`/api/admin/nodes/${nodeID.value}/exits`,{method:'PUT',body:JSON.stringify(nodeRouting(defaultExit.value,routeRules.value,globalExit.value))});routeModal.value=false;message.success('路由已保存，将在节点下一次成功刷新配置时应用')}catch(e){routeError.value=(e as Error).message}finally{saving.value=false}}
onMounted(load)
</script>
<template>
 <div class="page-heading"><div><span class="eyebrow">EXITS & ROUTING</span><h1>落地与路由</h1><p>粘贴节点链接，选择节点的默认出站或按域名、网段分流。</p></div><div class="button-row"><n-button :loading="busy" @click="load">刷新</n-button><n-button @click="routeModal=true;selectNode(nodeID)">节点路由</n-button><n-button type="primary" @click="openImport">粘贴链接导入</n-button></div></div>
 <n-alert v-if="error&&!show" type="error" class="space-bottom">{{error}}</n-alert>
 <article class="surface"><div class="section-heading"><div><h2>落地代理</h2><p>{{rows.length}} 条记录 · 凭据加密保存</p></div></div><n-data-table :row-key="(row:any)=>row.id" :columns="columns" :data="rows" :loading="busy" :bordered="false" :scroll-x="900" :pagination="{pageSize:15}"/><p class="table-note">列表隐藏凭据。编辑时仅向管理员读取完整参数；停用后配置下发会报错，正在运行的节点仍保留上次成功配置，需检查节点状态。</p></article>
 <n-modal v-model:show="show" preset="card" title="粘贴节点链接" class="resource-modal" :bordered="false" @after-leave="profiles=[];links=''">
 <n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><p class="muted">每行一条链接，最多 200 行。支持 SOCKS5、HTTP(S)、VLESS、VMess、SS、Trojan、Hysteria2、AnyTLS。链接在面板本地解析。</p>
 <n-input v-if="!previewed" v-model:value="links" type="textarea" :autosize="{minRows:7,maxRows:14}" placeholder="socks5://用户名:密码@地址:1080#落地名称" :input-props="{spellcheck:false,autocomplete:'off'}"/>
 <template v-else><n-alert v-if="!storageReady" type="warning" class="space-bottom">请先在部署环境配置 LUMA_MASTER_KEY，才能保存落地。</n-alert><n-alert v-for="issue in issues" :key="issue.line" type="warning" class="space-bottom">第 {{issue.line}} 行：{{issue.message}}</n-alert><p v-if="!profiles.length">没有可导入的节点。</p><div v-for="(p,i) in profiles" :key="i" class="exit-preview"><div class="button-row"><n-checkbox v-model:checked="p.selected">{{p.protocol.toUpperCase()}}</n-checkbox><n-button size="small" text @click="edit(p,i)">完整参数</n-button></div><div class="form-two"><n-form-item label="名称"><n-input v-model:value="p.name" :maxlength="100"/></n-form-item><n-form-item label="服务器"><n-input v-model:value="p.server"/></n-form-item><n-form-item label="端口"><n-input-number v-model:value="p.port" :min="1" :max="65535" :precision="0"/></n-form-item></div></div></template>
 <template #footer><div class="modal-footer"><n-button @click="show=false">取消</n-button><n-button v-if="previewed" @click="previewed=false;profiles=[]">重新粘贴</n-button><n-button v-if="!previewed" type="primary" :loading="saving" :disabled="!links.trim()" @click="parse">解析并预览</n-button><n-button v-else type="primary" :loading="saving" :disabled="!storageReady||!profiles.some(p=>p.selected)" @click="saveImport">保存所选落地</n-button></div></template></n-modal>
 <n-modal v-model:show="editor" preset="card" title="编辑完整落地参数" class="resource-modal" :bordered="false" @after-leave="editJSON=''">
 <n-alert v-if="editError" type="error" class="space-bottom">{{editError}}</n-alert><p class="muted">此处包含密码等连接参数。修改后会替换完整配置；只需改名称或地址时，请保留其他字段。</p><n-input v-model:value="editJSON" type="textarea" class="code-input" :autosize="{minRows:12,maxRows:22}" :input-props="{spellcheck:false,autocomplete:'off'}"/><template #footer><div class="modal-footer"><n-button @click="editor=false">取消</n-button><n-button type="primary" :loading="saving" @click="saveEdit">保存参数</n-button></div></template></n-modal>
 <n-modal v-model:show="routeModal" preset="card" title="节点出站与分流" class="resource-modal" :bordered="false"><n-alert v-if="routeError" type="error" class="space-bottom">{{routeError}}</n-alert><n-form-item label="节点"><n-select :value="nodeID" :options="nodes.map(n=>({label:n.name,value:n.id}))" @update:value="selectNode"/></n-form-item><template v-if="nodeID"><NodeRouting v-model:global-exit="globalExit" v-model:default-exit="defaultExit" v-model:rules="routeRules" :exits="rows" :machine-id="nodes.find(n=>n.id===nodeID)?.machine_id" :kernel-type="nodes.find(n=>n.id===nodeID)?.config?.kernel_type||'singbox'"/></template><template #footer><div class="modal-footer"><n-button @click="routeModal=false">取消</n-button><n-button type="primary" :disabled="!nodeID" :loading="saving" @click="saveRoutes">保存路由</n-button></div></template></n-modal>
</template>
<style scoped>.exit-preview{padding:16px;margin:12px 0;border:1px solid var(--border,#dfe5e1);border-radius:10px}.exit-preview h3{margin:0}@media(max-width:640px){.page-heading{flex-direction:column;align-items:stretch}.page-heading>.button-row{flex-wrap:wrap}}</style>
